// Isolated loopback peer for the unchanged TypeScript pipe transport.
import { createServer } from 'node:http';
import { connect } from 'node:net';
import { once } from 'node:events';
import { WebSocketServer } from 'ws';
import { proxyTransport } from '../../dist/packages/host-runtime/src/codex-proxy-transport.js';

const http = createServer();
const peers = new WebSocketServer({ server: http, perMessageDeflate: false });
const deadline = setTimeout(() => { throw new Error('Proxy oracle timed out'); }, 5000);
http.listen(0, '127.0.0.1');
await once(http, 'listening');
const connection = once(peers, 'connection');
const pipe = connect(http.address().port, '127.0.0.1');
const transport = await proxyTransport(pipe, pipe);
const [socket] = await connection;
const trace = [];
const sent = once(socket, 'message');
await new Promise((resolve, reject) => transport.input.write('{"hello":"Grüße😀"}\n', error => error ? reject(error) : resolve()));
const [message, binary] = await sent;
if (binary) throw new Error('Outbound frame must be text');
trace.push(message.toString());
const output = transport.output[Symbol.asyncIterator]();
const fragmented = Buffer.from('{"result":"Grüße"}');
socket.send(fragmented.subarray(0, 14), { binary: false, fin: false });
const pong = once(socket, 'pong');
socket.ping('probe');
await pong;
socket.send(fragmented.subarray(14), { binary: false, fin: true });
trace.push((await output.next()).value.toString());
socket.send('', { binary: false });
trace.push((await output.next()).value.toString());
const closed = once(socket, 'close');
await transport.close();
await transport.close();
const [code, reason] = await closed;
trace.push(`${code}:${reason}`);
peers.close();
http.close();
clearTimeout(deadline);
console.log(JSON.stringify(trace));
